style.css:
@-moz-document domain("roblox.com") {
/* Change the color of the Play button to PBS Kids Green and round the corners */
    .btn-common-play-game-lg,
    .game-card-container .game-card-play .btn-control-play,
    .game-card-container .game-card-play .icon-play {
        background-color: #99CF16 !important; /* PBS Kids Green */
        border-color: #2638C4 !important; /* PBS Blue border */
        border-radius: 40px !important;
        font-family: "Comic Sans MS", "Arial Black", sans-serif !important;
        color: #FFFFFF !important;
        text-shadow: 2px 2px 0px rgba(0, 0, 0, 0.2) !important;
        transition: all 0.2s ease-in-out;
    }

    /* Add a bouncy hover effect for a cartoonish PBS vibe */
    .btn-common-play-game-lg:hover,
    .game-card-container .game-card-play .btn-control-play:hover {
        background-color: #F7E03B !important; /* PBS Kids Yellow */
        transform: scale(1.05);
    }

    /* Change the standard play icon inside the button if needed */
    .btn-common-play-game-lg .icon-common-play {
        filter: drop-shadow(2px 2px 0px rgba(0, 0, 0, 0.3));
    }
}
